@Service
public class OrderService {
    private final OrderRepository repository;
    private final PriceCalculator calculator;

    public OrderService(OrderRepository repository, PriceCalculator calculator) {
        this.repository = repository;
        this.calculator = calculator;
    }

    public Order processOrder(Long orderId) {
        var order = repository.findById(orderId).orElseThrow();
        // Set breakpoint here to inspect order state
        var discount = calculator.calculateDiscount(order);
        order.setDiscount(discount);
        // Set another breakpoint here to verify discount was applied
        var total = calculator.calculateTotal(order);
        order.setTotal(total);
        return repository.save(order);
    }
}

