void checkout(Order order) {
    BigDecimal total = order.total();              // (breakpoint paused here)
    BigDecimal discount = calculateDiscount(order); // STEP OVER -> runs whole method, next line
                                                    // STEP INTO -> jumps inside calculateDiscount(...)
    BigDecimal payable = total.subtract(discount);
    save(order, payable);
}

BigDecimal calculateDiscount(Order order) {
    var tier = order.customer().tier();   // if you STEP INTO above, you land here
    return rules.discountFor(tier);       // STEP OUT -> finishes this method, back to checkout()
}
