@Service
public class OrderProcessor {
    private final DiscountCalculator discountCalculator;
    private final TaxCalculator taxCalculator;

    public Invoice processOrder(Order order) {
        // Add watch: order.getItems().size()
        var subtotal = order.getItems().stream()
            .mapToDouble(Item::getPrice)
            .sum();
        // Add watch: subtotal

        var discount = discountCalculator.calculate(order);
        // Add watch: discount / subtotal * 100 (discount percentage)

        var discountedTotal = subtotal - discount;
        var tax = taxCalculator.calculate(discountedTotal);
        // Add watch: discountedTotal + tax

        return new Invoice(order.getId(), subtotal, discount, tax);
    }
}

@Service
public class OrderBatchProcessor {
    private final OrderRepository repository;
    private final OrderValidator validator;

    public BatchResult processBatch(List<Order> orders) {
        var results = new ArrayList<OrderResult>();

        for (int i = 0; i < orders.size(); i++) {
            var order = orders.get(i);
            // Set conditional breakpoint here: i == 437 || order.getId() == 54321L
            // This pauses only on iteration 437 or when processing order 54321

            if (!validator.isValid(order)) {
                results.add(OrderResult.invalid(order.getId()));
                continue;
            }

            var processed = processOrder(order);
            results.add(processed);
        }

        return new BatchResult(results);
    }
}
